     <title>Computer Languages Quiz</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f5f7fb;
         --surface: #ffffff;
         --surface-muted: #eef2ff;
         --text: #162033;
         --text-muted: #4c5875;
         --border: #d7def2;
         --border-strong: #8ea0cf;
         --accent: #375dfb;
         --accent-strong: #2547d0;
         --success-bg: #ecfdf3;
         --success-text: #0f7a42;
         --error-bg: #fff1f2;
         --error-text: #b42318;
         --shadow: 0 24px 60px rgba(27, 39, 94, 0.12);
         --radius: 20px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
         background:
           radial-gradient(circle at top left, #e7edff 0, transparent 32%),
           linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
         color: var(--text);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: -3rem;
         padding: 0.75rem 1rem;
         border-radius: 0.75rem;
         background: var(--text);
         color: #fff;
         text-decoration: none;
         z-index: 10;
       }

       .skip-link:focus {
         top: 1rem;
       }

       main {
         width: min(100%, 760px);
         margin: 0 auto;
         padding: 3rem 1rem 4rem;
       }

       .quiz-shell {
         background: rgba(255, 255, 255, 0.94);
         border: 1px solid rgba(255, 255, 255, 0.8);
         border-radius: 28px;
         box-shadow: var(--shadow);
         padding: clamp(1.5rem, 3vw, 2.5rem);
         backdrop-filter: blur(14px);
       }

       .eyebrow {
         margin: 0 0 0.75rem;
         font-size: 0.85rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
         color: var(--accent);
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 5vw, 3rem);
         line-height: 1.1;
       }

       .intro {
         margin: 1rem 0 0;
         max-width: 58ch;
         color: var(--text-muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         margin-top: 2rem;
       }

       .form-field {
         margin-bottom: 1.25rem;
       }

       fieldset {
         margin: 0;
         padding: 1.25rem;
         border: 1px solid var(--border);
         border-radius: var(--radius);
         background: var(--surface);
       }

       .form-field.is-invalid fieldset {
         border-color: var(--error-text);
         box-shadow: 0 0 0 3px rgba(180, 35, 24, 0.12);
       }

       legend {
         padding: 0 0.4rem;
         font-size: 1.05rem;
         font-weight: 700;
       }

       .help-text,
       .question-note,
       .error-text {
         margin: 0.5rem 0 0;
         line-height: 1.5;
       }

       .help-text,
       .question-note {
         color: var(--text-muted);
       }

       .error-text {
         color: var(--error-text);
         font-weight: 600;
       }

       .option-list {
         display: grid;
         gap: 0.75rem;
         margin-top: 1rem;
       }

       .option {
         display: flex;
         align-items: flex-start;
         gap: 0.85rem;
         padding: 0.95rem 1rem;
         border: 1px solid var(--border);
         border-radius: 16px;
         background: linear-gradient(180deg, #ffffff 0%, #fbfcff 100%);
         transition: border-color 150ms ease, transform 150ms ease, box-shadow 150ms ease;
       }

       .option:hover {
         border-color: var(--border-strong);
         transform: translateY(-1px);
       }

       .option input {
         width: 1.1rem;
         height: 1.1rem;
         margin-top: 0.15rem;
         accent-color: var(--accent);
       }

       .option span {
         line-height: 1.5;
       }

       .option:focus-within {
         outline: 3px solid rgba(55, 93, 251, 0.24);
         outline-offset: 2px;
         border-color: var(--accent);
       }

       .actions {
         display: flex;
         align-items: center;
         gap: 1rem;
         flex-wrap: wrap;
         margin-top: 1.75rem;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.5rem;
         font: inherit;
         font-weight: 700;
         color: #fff;
         background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
         cursor: pointer;
         box-shadow: 0 14px 30px rgba(55, 93, 251, 0.28);
       }

       button:hover {
         transform: translateY(-1px);
       }

       button:focus-visible {
         outline: 3px solid rgba(55, 93, 251, 0.28);
         outline-offset: 3px;
       }

       .results {
         flex: 1 1 260px;
         min-height: 3.5rem;
         padding: 0.95rem 1rem;
         border-radius: 16px;
         background: var(--surface-muted);
         color: var(--text);
       }

       .results.success {
         background: var(--success-bg);
         color: var(--success-text);
       }

       .results.error {
         background: var(--error-bg);
         color: var(--error-text);
       }

       @media (max-width: 640px) {
         main {
           padding: 1.25rem 0.85rem 2rem;
         }

         .quiz-shell {
           border-radius: 22px;
         }

         fieldset {
           padding: 1rem;
         }
       }

       @media (forced-colors: active) {
         body {
           background: Canvas;
           color: CanvasText;
         }

         .quiz-shell,
         fieldset,
         .option,
         .results {
           border-color: ButtonText;
           background: Canvas;
           box-shadow: none;
         }

         .skip-link,
         button {
           border: 1px solid ButtonText;
           background: ButtonFace;
           color: ButtonText;
           box-shadow: none;
